#!/usr/bin/env node
/**
 * generate-llms-full.js — llms-full.txt generator (AEO).
 *
 * Serializes the project's own static HTML surfaces (demo/, showcase/, and
 * frontend/ when present) to markdown and concatenates them into
 * public/llms-full.txt — the full-content companion to the llms.txt index
 * generated by generate-project-artifacts.js.
 *
 * Forward-only serialization of trusted, first-party HTML: a mechanical
 * transform (headings, lists, links, emphasis, tables, code) — the same
 * content agents get from rendering, without any parsing of third-party
 * markup.
 *
 * Generated artifact: never hand-edit; `npm run generate:llms-full` is
 * idempotent (byte-stable output for unchanged sources).
 *
 * Usage: npm run generate:llms-full
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..', '..');
const OUTPUT = path.join(ROOT, 'public', 'llms-full.txt');
const SCOPES = ['demo', 'showcase', 'frontend'];

const walk = (dir, out = []) => {
    if (!fs.existsSync(dir)) return out;
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const p = path.join(dir, entry.name);
        if (entry.isDirectory()) walk(p, out);
        else if (entry.name.endsWith('.html')) out.push(p);
    }
    return out;
};

function decodeEntities(text) {
    return text
        .replaceAll('&amp;', '&')
        .replaceAll('&lt;', '<')
        .replaceAll('&gt;', '>')
        .replaceAll('&quot;', '"')
        .replaceAll('&#39;', "'")
        .replaceAll('&apos;', "'");
}

function htmlToMarkdown(html, sourcePath) {
    const md = [];

    // Headings
    html = html.replace(/<h([1-6])[^>]*>([\s\S]*?)<\/h\1>/gi, (_, level, inner) => {
        md.push(`${'#'.repeat(Number(level))} ${stripTags(inner).trim()}`);
        return '';
    });

    // Block <pre> → fenced code; inline <code> stays inline as backticks
    html = html.replace(/<pre[^>]*>([\s\S]*?)<\/pre>/gi, (_, inner) => {
        md.push('```\n' + decodeEntities(stripTags(inner)).trim() + '\n```');
        return '';
    });
    html = html.replace(/<code[^>]*>([\s\S]*?)<\/code>/gi, (_, inner) => `\`${decodeEntities(stripTags(inner)).trim()}\``);

    // Tables → pipe tables (thead+tbody rows)
    html = html.replace(/<table[^>]*>([\s\S]*?)<\/table>/gi, (_, table) => {
        const rows = [...table.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)].map((row) =>
            [...row[1].matchAll(/<t[hd][^>]*>([\s\S]*?)<\/t[hd]>/gi)].map((cell) => stripTags(cell[1]).trim())
        );
        if (rows.length) {
            md.push('| ' + rows[0].join(' | ') + ' |');
            md.push('| ' + rows[0].map(() => '---').join(' | ') + ' |');
            for (const row of rows.slice(1)) md.push('| ' + row.join(' | ') + ' |');
        }
        return '';
    });

    // Lists (flatten to md bullets)
    html = html.replace(/<li[^>]*>([\s\S]*?)<\/li>/gi, (_, inner) => {
        md.push(`- ${stripTags(inner).trim()}`);
        return '';
    });

    // Links and images (inline)
    html = html.replace(/<a\s[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, (_, href, inner) => `[${stripTags(inner).trim()}](${href})`);
    html = html.replace(/<img\s[^>]*src=["']([^"']+)["'][^>]*>/gi, (_, src) => `![image](${src})`);
    html = html.replace(/<(strong|b)[^>]*>([\s\S]*?)<\/\1>/gi, (_, __, inner) => `**${stripTags(inner).trim()}**`);
    html = html.replace(/<(em|i)[^>]*>([\s\S]*?)<\/\1>/gi, (_, __, inner) => `*${stripTags(inner).trim()}*`);

    // Remaining block text → paragraphs
    const body = html.match(/<body[^>]*>([\s\S]*?)<\/body>/i)?.[1] ?? html;
    for (const block of body.split(/<(?:\/p|\/div|\/section|\/article|br)\s*\/?>/i)) {
        const text = decodeEntities(stripTags(block)).replace(/\s+/g, ' ').trim();
        if (text) md.push(text);
        if (text) md.push('');
    }

    return md.join('\n');
}

function stripTags(html) {
    return String(html).replace(/<[^>]*>/g, ' ');
}

const sections = [];
let count = 0;

for (const scope of SCOPES) {
    const files = walk(path.join(ROOT, scope)).sort();
    for (const file of files) {
        const rel = path.relative(ROOT, file).replaceAll(path.sep, '/');
        const html = fs.readFileSync(file, 'utf8');
        const title = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1]?.trim() || rel;
        sections.push(`\n\n---\n\n# ${title}\n\nSource: ${rel}\n\n${htmlToMarkdown(html, rel).trim()}`);
        count += 1;
    }
}

fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
fs.writeFileSync(
    OUTPUT,
    `# CSMA — full content for agents (llms-full.txt)\n\nGenerated from the project's static HTML surfaces (${SCOPES.join(', ')}). Regenerate: \`npm run generate:llms-full\`. Never hand-edit.\n${sections.join('')}\n`,
    'utf8'
);

console.log(`[generate:llms-full] ${count} page(s) serialized → ${path.relative(ROOT, OUTPUT)}`);
